import{_ as t,o as i,c as a,a3 as r}from"./chunks/framework.DAK02U1-.js";const u=JSON.parse('{"title":"Building from Source","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Building from Source | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/catter/dev/build"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/catter/dev/build"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/catter/dev/build"}]]},"headers":[],"relativePath":"catter/dev/build.md","filePath":"en/catter/dev/build.md","lastUpdated":1792917719000}'),s={name:"catter/dev/build.md"};function n(l,e,o,d,h,c){return i(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="building-from-source" tabindex="-1">Building from Source <a class="header-anchor" href="#building-from-source" aria-label="Permalink to &quot;Building from Source&quot;">​</a></h1><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="https://pixi.sh" target="_blank" rel="noreferrer">pixi</a> -- Environment and dependency management</li><li><a href="https://xmake.io/" target="_blank" rel="noreferrer">XMake</a> -- Build system (not installed by pixi; install separately)</li><li>Git</li></ul><h2 id="supported-platforms" tabindex="-1">Supported Platforms <a class="header-anchor" href="#supported-platforms" aria-label="Permalink to &quot;Supported Platforms&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Platform</th><th>Toolchain</th></tr></thead><tbody><tr><td>Windows (win-64)</td><td>MSVC (VS2022)</td></tr><tr><td>Linux (linux-64)</td><td>GCC 14.2</td></tr><tr><td>macOS (osx-arm64)</td><td>xclang 23.1.2</td></tr><tr><td>Windows (win-64), <code>mingw</code> environment</td><td>xclang 23.1.2 (MinGW)</td></tr><tr><td>Windows on ARM (win-64, emulated)</td><td>MSVC, for ARM64</td></tr></tbody></table><p>The <code>mingw</code> environment builds for Windows with <a href="https://github.com/clice-io/xclang" target="_blank" rel="noreferrer">xclang</a> instead of MSVC: <code>pixi run -e mingw cfg debug</code>, then <code>pixi run -e mingw build</code>.</p><p>Every Windows build also makes the hook DLL of the other architecture, x64 and ARM64 both: with MSVC, install the C++ build tools for ARM64 (and on Windows on ARM, those for x64) beside the default ones in the Visual Studio Installer.</p><h2 id="build-commands" tabindex="-1">Build Commands <a class="header-anchor" href="#build-commands" aria-label="Permalink to &quot;Build Commands&quot;">​</a></h2><p>All builds are managed through pixi tasks:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Configure the build (mode: debug, release, or releasedbg)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cfg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> debug</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build the project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Configure in release mode</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pixi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cfg</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span></span></code></pre></div><h2 id="build-system" tabindex="-1">Build System <a class="header-anchor" href="#build-system" aria-label="Permalink to &quot;Build System&quot;">​</a></h2><p>The project uses <a href="https://xmake.io/" target="_blank" rel="noreferrer">XMake</a> as the build system, managed through pixi tasks. The C++ standard is C++23.</p><h3 id="build-targets" tabindex="-1">Build Targets <a class="header-anchor" href="#build-targets" aria-label="Permalink to &quot;Build Targets&quot;">​</a></h3><ul><li><code>catter</code> -- Main CLI executable (the DECISION daemon)</li><li><code>catter-proxy</code> -- Proxy process manager</li><li><code>catter-hook-unix</code> -- Unix hook shared library (Linux/macOS)</li><li><code>catter-hook-x64</code>, <code>catter-hook-arm64</code> -- Windows hook DLLs, one per architecture, both built by every Windows build</li><li><code>catter-core</code> -- Core library</li><li><code>common</code> -- Shared utilities library</li></ul><h2 id="key-dependencies" tabindex="-1">Key Dependencies <a class="header-anchor" href="#key-dependencies" aria-label="Permalink to &quot;Key Dependencies&quot;">​</a></h2><ul><li><a href="https://github.com/gabime/spdlog" target="_blank" rel="noreferrer">spdlog</a> (1.15.3) -- Logging</li><li><a href="https://github.com/clice-io/kotatsu" target="_blank" rel="noreferrer">kotatsu</a> -- Async runtime, testing framework, option parsing</li><li><a href="https://github.com/microsoft/Detours" target="_blank" rel="noreferrer">Microsoft Detours</a> -- Windows API hooking and DLL injection (Windows only)</li></ul>`,16)])])}const g=t(s,[["render",n]]);export{u as __pageData,g as default};
